def robust_z_score(net_series):
    """Computes the robust z-score for a given series of net values."""
    group_median = net_series.median()
    abs_dev = abs(net_series - group_median)
    mad = abs_dev.median()
    if mad == 0:
        return pd.Series(0, index=net_series.index)  # or np.zeros_like(net_series)
